    if ((body_a == NULL) || (body_b == NULL) || (ref_a == NULL) || (ref_b == NULL) ||
        (c_bi == NULL) || (primary_index == NULL) || (geometry_quality == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!isfinite(variance_a)) || (variance_a <= 0.0) || (!isfinite(variance_b)) || (variance_b <= 0.0)) {
        return ADCS_E_RANGE;
    }

    adcs_vec3_t norm_ref_a, norm_ref_b;
    if (adcs_vec3_normalize(ref_a, ADCS_EPS_NORM, &norm_ref_a) != ADCS_OK) {
        return ADCS_E_RANGE;
    }
    if (adcs_vec3_normalize(ref_b, ADCS_EPS_NORM, &norm_ref_b) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    adcs_vec3_t norm_body_a, norm_body_b;
    if (adcs_vec3_normalize(body_a, ADCS_EPS_NORM, &norm_body_a) != ADCS_OK) {
        return ADCS_E_RANGE;
    }
    if (adcs_vec3_normalize(body_b, ADCS_EPS_NORM, &norm_body_b) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    adcs_vec3_t cross_ref = adcs_vec3_cross(&norm_ref_a, &norm_ref_b);
    double sine_sep = adcs_vec3_norm(&cross_ref);
    if (sine_sep <= ADCS_EPS_COLLINEAR) {
        return ADCS_E_DEGENERATE;
    }

    int p_idx = 0;
    if (variance_a > variance_b) {
        p_idx = 1;
    }
    *primary_index = p_idx;

    adcs_status_t status;
    if (p_idx == 0) {
        status = adcs_triad(&norm_body_a, &norm_body_b, &norm_ref_a, &norm_ref_b, c_bi);
    } else {
        status = adcs_triad(&norm_body_b, &norm_body_a, &norm_ref_b, &norm_ref_a, c_bi);
    }

    if (status != ADCS_OK) {
        return status;
    }

    double selected_variance = (p_idx == 0) ? variance_a : variance_b;
    *geometry_quality = sine_sep / selected_variance;

    return ADCS_OK;
}

